import json, math
def sig(z):
    return 1.0 / (1.0 + math.exp(-z))
h = [0.0, 0.0]
for x in [1.0, -2.0, 0.5]:
    f = [sig(2.0 * x), sig(-1.0 * x + 0.5)]
    u = [x, 3.0 * x]
    h = [f[i] * h[i] + (1.0 - f[i]) * u[i] for i in range(2)]
print(json.dumps({"carried": [round(v, 6) for v in h]}))
